import React from "react";
import "./index.scss";

const SECTION_IDS = ["about", "portfolio", "contact"];
const NAV_OFFSET = 80; // height of your top nav bar

const ScrollArrow = () => {
  const handleClick = () => {
    // Collect the sections that actually exist on the page, in order
    const sections = SECTION_IDS
      .map((id) => {
        const el = document.getElementById(id);
        if (!el) return null;
        return {
          id,
          el,
          top: el.offsetTop,
        };
      })
      .filter(Boolean);

    if (!sections.length) return;

    const scrollY = window.scrollY || window.pageYOffset;
    const viewportCenter = scrollY + window.innerHeight / 2;

    // Find the *next* section whose top is below the current viewport center
    let next = null;
    for (let i = 0; i < sections.length; i += 1) {
      if (sections[i].top - NAV_OFFSET > viewportCenter) {
        next = sections[i];
        break;
      }
    }

    if (next) {
      // Scroll smoothly to that section, minus nav offset
      const targetY =
        next.el.getBoundingClientRect().top +
        window.scrollY -
        NAV_OFFSET;

      window.scrollTo({
        top: targetY,
        behavior: "smooth",
      });
    } else {
      // If we're already past the last section, go back to the top
      window.scrollTo({
        top: 0,
        behavior: "smooth",
      });
    }
  };

  return (
    <button
      type="button"
      className="scroll-arrow"
      onClick={handleClick}
      aria-label="Scroll"
    >
      {/* Re-use your existing arrow icon style */}
      <span className="scroll-arrow-icon">↑</span>
    </button>
  );
};

export default ScrollArrow;
